import pathlib
root=pathlib.Path(__file__).resolve().parents[1]
for name in ['tools/package.py','tools/launch-packaged-server.py','tools/jar-inventory.py','README.md']:
    p=root/name;p.write_text(p.read_text(encoding='utf-8').replace('1.0.0','1.1.0'),encoding='utf-8')
p=root/'README.md';text=p.read_text(encoding='utf-8')
text=text.replace('**F7**','**Comma ( , )**').replace('**F8**','**Period ( . )**')
text=text.replace('Face depth ranges from **0 to 2 model units**, default **0.85**. Zero flattens the actual triangle surface. Head coverings cap protrusion to 0.40 units so it stays underneath their shell.','Face depth ranges from **0 to 6 model units**, default **1.75**. Zero flattens the triangle surface. Fully transparent outer-head fronts allow full depth even with the outer layer enabled. Opaque outer-front pixels or head equipment conservatively cap protrusion to 0.40 units to keep geometry beneath coverings.\n* **Face size** ranges from **10% to 400%** of the original footprint. Width and height scale about the head-face center; depth has its own independent slider. **Reset size** restores **100%**, exactly the previous version\'s face proportions. The sender\'s size is transmitted to nearby clients. Large sizes deliberately extend outside the normal 8×8 head footprint.')
text=text.replace('All vertices are limited to 0.40 protrusion whenever the outer head layer or head equipment is present.','All vertices are limited to 0.40 protrusion when head equipment is present or the enabled outer-head front contains visible pixels. A bounded render-thread cache inspects skin alpha so completely transparent fronts do not flatten the face.')
text=text.replace('Disable the outer head layer in Minecraft Skin Customization to see full configured depth when no head equipment is worn.','A completely transparent outer-front layer allows full depth already. If the front contains opaque pixels, disable the outer head layer in Minecraft Skin Customization to see full configured depth when no head equipment is worn.')
text=text.replace('Client preferences are stored in','Upgrading to 1.1.0 migrates the old F7/F8 defaults to comma/period and the untouched 0.85 depth default to 1.75. Other custom keybindings and depth values are preserved. Update the mod on the server and all clients together: networking protocol 2 carries face size and is incompatible with 1.0.0.\n\nClient preferences are stored in')
p.write_text(text,encoding='utf-8')
